arguments.command:
cd /testbed && python3 -c "
import re
pattern = re.compile(r'(?<=.)(-|\+|\^|\s+)(?=.)')

# Test cases from PR description
test_cases = ['-', '+', 'Shift-+']
print('PR Test Cases:')
for case in test_cases:
    parts = pattern.split(case)
    print(f'  {repr(case):15s} -> {parts}')
    if len(parts) == 1:
        print(f'    Single kbd element with content: {repr(parts[0])}')
    else:
        print('    Compound kbd:')
        for i, part in enumerate(parts):
            if i % 2 == 0:
                print(f'      Key: {repr(part)}')
            else:
                print(f'      Sep: {repr(part)}')
    print()
"

